// The two assets the "Open in app" fallback pages draw with (lib/app-fallback-page.ts), as data: URIs: those pages carry
// a live credential in their URL fragment, so they ask for nothing but their own document. Server-only. They are
// constants, not files read at run time, so the standalone build cannot ship the page without them.
//   * the logo is public/brand/seazn-logo-night-tight.png, byte for byte (app-fallback-page.test.ts compares them);
//   * the faces are Barlow Condensed's latin subset, weights 500 and 700 — the woff2 files next/font/google emits for
//     the marketing display face (components/marketing/marketing-shell.tsx). OFL: assets/fonts/OFL-BarlowCondensed.txt.
export const LOGO_DATA_URI =
  "data:image/png;base64,";

export const DISPLAY_500_DATA_URI =
  "data:font/woff2;base64,";

export const DISPLAY_700_DATA_URI =
  "data:font/woff2;base64,";
